edges = [(2,6), (5,7), (2,5), (1,2), (4,6), (3,6), (1,5), (0,1), (0,8)]
# Check connectivity
from collections import defaultdict
g = defaultdict(set)
for u,v in edges:
    g[u].add(v); g[v].add(u)
seen = {0}; stack=[0]
while stack:
    x = stack.pop()
    for y in g[x]:
        if y not in seen:
            seen.add(y); stack.append(y)
print(len(seen)==9, seen)
